{
  "qid": "t2i_0009_l3_001",
  "sample_id": "0009",
  "gen_prompt": "画广东醒狮在老祠堂前全身表演，一道闪电突然照亮它面前高悬的生菜和红包。",
  "invocation": "L3",
  "knowledge_dim": "广东醒狮采青表演与传统道具形制",
  "fidelity_checks": [
    {
      "check": "狮头必须与高悬的生菜、红包形成明确的采青互动趋势，如张口、俯探、跃起、低头、爪部靠近或衔咬方向，而不是与普通道具无关的站立。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["4"],
        "derivation_chain": "前提：题面给出“面前高悬的生菜和红包” → 知识：广东醒狮表演中“采青”是核心仪式，青常为悬挂物 → 清单[4]：醒狮必须处于被舞动的表演状态 → 视觉结论：狮头应呈现采青动作趋势并与悬挂物形成明确互动。"
      },
      "rubric": {
        "tier_0": "狮头与生菜、红包没有采青关系：背对、远离、平视无关，或二者只是普通背景物；狮头与悬挂物不可见。",
        "tier_1": "狮头朝向或接近生菜、红包，但缺少明确的咬、探、挑、俯冲、张口等采青动作趋势，互动关系弱。",
        "tier_2": "狮头与生菜、红包同框，且狮头通过张口、低头、前探、跃起、爪部靠近或衔咬方向等形成清晰采青动作趋势。"
      },
      "variants_used": "无",
      "visibility_requirement": "狮头与至少一个高悬物必须同框可见；若生菜、红包或狮头因裁切完全不可见，本条判0；若局部遮挡但动作趋势可辨，可按及格或满分。",
      "weight": 1.0
    },
    {
      "check": "狮身躯干必须表现为被舞动的布制狮被，并随表演动作呈现褶皱、垂坠或飘动，狮被下缘可见舞狮者腿脚或身体支撑。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["4", "5"],
        "derivation_chain": "前提：题面要求“全身表演” → 知识：广东醒狮为舞狮者支撑的传统道具表演 → 清单[5]：狮身躯干必须由彩色布制狮被构成 → 清单[4]：狮被下方可见舞狮者腿脚或身体 → 视觉结论：狮被应呈现织物动态且有表演者支撑。"
      },
      "rubric": {
        "tier_0": "狮身呈实心雕塑、动物皮毛、无支撑漂浮物，或画面为无人静态摆设；狮被下缘完全看不到舞狮者腿脚或身体。",
        "tier_1": "狮身可辨为织物，但动态较弱、褶皱呆板，或舞狮者支撑仅隐约可见、身体关系不明确。",
        "tier_2": "狮身明确为布制狮被，因表演动作出现自然褶皱、垂坠或飘动；狮被下缘可见舞狮者腿脚或身体，允许因动作造成局部遮挡。"
      },
      "variants_used": "狮被常带流苏或绒毛镶边，但流苏、绒毛镶边不是满分必要条件。",
      "visibility_requirement": "题面要求全身表演，狮被下缘应可见；若构图裁切导致狮被下缘完全不可见，本条判0；若局部遮挡但可辨织物与支撑，可按及格或满分。",
      "weight": 1.0
    },
    {
      "check": "狮头必须呈现装饰化、夸张彩绘的南狮道具造型，并具备额前独角状突起、大而圆的凸眼、宽大嘴部三项标志性特征。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["1", "2", "3"],
        "derivation_chain": "前提：题面点名“广东醒狮” → 清单[1]：主体必须为装饰化、夸张彩绘的南狮狮头道具 → 清单[2]：额前必须有独角状突起 → 清单[3]：必须有凸眼与宽大嘴部 → 视觉结论：狮头应同时可辨南狮道具的三项标志性造型。"
      },
      "rubric": {
        "tier_0": "狮头为写实生物学狮子、北狮无角写实头型，或完全缺少额前突起、凸眼、宽大嘴部中的关键特征。",
        "tier_1": "整体接近南狮道具，但三项标志性特征中仅部分清晰可辨，或造型被过度简化导致辨识度不足。",
        "tier_2": "狮头为装饰化夸张彩绘南狮道具，额前独角状突起、大而圆凸眼、宽大嘴部三项特征均清晰可辨。"
      },
      "variants_used": "无",
      "visibility_requirement": "狮头至少正面或侧面可见；若狮头完全不可见，本条判0；若因透视、遮挡导致某特征不明显但整体可辨，可按及格；三项特征均可辨为满分。",
      "weight": 1.0
    },
    {
      "check": "狮头主色必须属于传统角色脸谱配色体系，在闪电强光下仍保持主色可辨，不得变成随机霓虹色、塑料彩虹色或无体系杂色。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["6"],
        "derivation_chain": "前提：题面给出“闪电突然照亮” → 知识：广东醒狮狮头按传统角色脸谱配色区分文化内涵 → 清单[6]：狮头主色必须属于传统角色脸谱配色体系 → 视觉结论：强光受光面与阴影面不得破坏传统主色体系。"
      },
      "rubric": {
        "tier_0": "狮头主色不属于刘备黄、关公红、张飞黑或其他传统南狮配色，呈现随机霓虹、塑料彩虹、无体系杂色。",
        "tier_1": "可辨某种传统主色倾向，但被闪电强光严重冲淡、偏色或杂色过多，角色配色体系不够稳定。",
        "tier_2": "狮头主色明确属于刘备黄、关公红、张飞黑或其他传统南狮配色之一，闪电受光后主色仍可辨且保持传统角色配色感。"
      },
      "variants_used": "刘备狮黄色、关公狮红色、张飞狮黑色、其他传统南狮配色均可。",
      "visibility_requirement": "狮头主色需可见；若主色因过曝或遮挡完全不可辨，本条判0；若部分过曝但主色可辨，可按及格或满分。",
      "weight": 1.0
    },
    {
      "check": "画面不得出现真实生物学形态的狮子充当或替代广东醒狮道具。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": ["7"],
        "derivation_chain": "前提：题面点名“广东醒狮” → 知识：广东醒狮是人工彩绘道具而非动物 → 清单[7]：不得出现真实生物学形态的狮子充当或替代醒狮道具 → 视觉结论：主体必须是道具化南狮造型。"
      },
      "rubric": {
        "tier_0": "画面出现真实生物学形态的狮子，或以写实狮子身体、头部替代醒狮道具。",
        "tier_1": "主体仍为醒狮道具，但局部出现明显写实狮毛、写实狮脸或动物化结构，造成轻微混淆。",
        "tier_2": "画面完全没有真实生物学狮子充当或替代醒狮道具，主体清晰为传统彩绘南狮道具。"
      },
      "variants_used": "无",
      "visibility_requirement": "任何真实狮子或写实狮替代均直接判0；若仅出现装饰性狮纹图案且未替代主体，不影响满分。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "广东醒狮必须作为画面主导主体出现，占据主要体量与视觉焦点。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "广东醒狮缺失、极小、被背景严重压过，或画面主体跑偏为生菜、红包、建筑。",
        "tier_1": "广东醒狮可辨但视觉主导性不足，主体与背景或其他元素争夺焦点。",
        "tier_2": "广东醒狮占据画面主导地位，体量、位置和视觉焦点均明确。"
      }
    },
    {
      "check": "广东醒狮必须呈现全身表演状态，而不是仅出现头部、局部或静态摆拍。",
      "facet": "fullbody_action",
      "rubric": {
        "tier_0": "没有全身表演，仅头部特写、局部裁切、静态摆设或无动作关系。",
        "tier_1": "可见部分身体但表演动作不完整，或全身姿态不明确。",
        "tier_2": "广东醒狮整体处于全身表演动作中，姿态、动势和表演状态清晰。"
      }
    },
    {
      "check": "场景必须为老祠堂前，并呈现一道闪电突然照亮的暗场强光环境。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "场景不是老祠堂前，或完全没有闪电照亮的暗场强光环境。",
        "tier_1": "有泛化中式建筑或普通夜景，但老祠堂特征与闪电瞬间氛围较弱。",
        "tier_2": "可辨老祠堂前场景，并清楚呈现闪电突然照亮的暗场强光环境。"
      }
    },
    {
      "check": "生菜和红包必须高悬于广东醒狮面前，空间关系合理且可辨。",
      "facet": "spatial_3d",
      "rubric": {
        "tier_0": "生菜或红包缺失，或它们位于地面、背景、狮头背后等不符合“面前高悬”的位置。",
        "tier_1": "生菜和红包存在，但高悬关系不清、位置偏后、遮挡严重或空间逻辑较弱。",
        "tier_2": "生菜和红包高悬于狮头面前，位置、遮挡和空间关系合理清晰。"
      }
    }
  ],
  "quality_facets": [
    "physical_logic",
    "edge_clarity",
    "noise",
    "resolution"
  ],
  "aesthetic_facets": [
    "composition",
    "lighting_atmosphere",
    "color_harmony"
  ],
